package org.apache.camel.reifier.language;

import org.apache.camel.CamelContext;
import org.apache.camel.model.language.ExpressionDefinition;
import org.apache.camel.model.language.JavaExpression;

public class JavaExpressionReifier extends TypedExpressionReifier<JavaExpression> {

    public JavaExpressionReifier(CamelContext camelContext, ExpressionDefinition definition) {
        super(camelContext, definition);
    }

    @Override
    protected Object[] createProperties() {
        Object[] properties = new Object[3];
        properties[0] = asResultType();
        properties[1] = parseBoolean(definition.getPreCompile());
        properties[2] = parseBoolean(definition.getSingleQuotes());
        return properties;
    }

    @Override
    public boolean isResolveOptionalExternalScriptEnabled() {
        // we handle this in camel-joor (joor is used for compiling java source at runtime)
        return false;
    }

}
